// tg68k_wrap.v -- the TG68K as cpu_wrapper.v instantiates it (lower-case port names, the six
// generics as parameters), around GHDL's Verilog translation of TG68KdotC_Kernel.vhd (module
// tg68k_ghdl, generated by build.sh with the same generic values).  Simulation only.
module TG68KdotC_Kernel #(parameter sr_read = 2, vbr_stackframe = 2, extaddr_mode = 2,
                          mul_mode = 2, div_mode = 2, bitfield = 2)
(
  input         clk,
  input         nreset,
  input         clkena_in,
  input  [15:0] data_in,
  input   [2:0] ipl,
  input         ipl_autovector,
  input   [1:0] cpu,
  output [31:0] addr_out,
  output [15:0] data_write,
  output        nwr,
  output        nuds,
  output        nlds,
  output  [1:0] busstate,
  output        longword,
  output        nresetout,
  output [31:0] regin_out,
  output  [3:0] cacr_out,
  output [31:0] vbr_out
);
  tg68k_ghdl k (.clk(clk), .nReset(nreset), .clkena_in(clkena_in), .data_in(data_in), .IPL(ipl),
    .IPL_autovector(ipl_autovector), .berr(1'b0), .CPU(cpu), .addr_out(addr_out),
    .data_write(data_write), .nWr(nwr), .nUDS(nuds), .nLDS(nlds), .busstate(busstate),
    .longword(longword), .nResetOut(nresetout), .FC(), .clr_berr(), .skipFetch(),
    .regin_out(regin_out), .CACR_out(cacr_out), .VBR_out(vbr_out));
endmodule
